) VALUES (
    'jarl-magnus-riiber-profile',
    '{"en": "Jarl Magnus Riiber: Nordic Combined''s Dominant Force", "de": "Jarl Magnus Riiber: Dominante Kraft der Nordischen Kombination", "fr": "Jarl Magnus Riiber : La force dominante du combiné nordique", "it": "Jarl Magnus Riiber: La forza dominante della combinata nordica", "es": "Jarl Magnus Riiber: La fuerza dominante de la combinada nórdica", "pt": "Jarl Magnus Riiber: A força dominante do combinado nórdico", "nl": "Jarl Magnus Riiber: De dominante kracht van de Noordse combinatie", "ar": "يارل ماغنوس ريبر: القوة المهيمنة للجمع الشمالي", "ja": "ヤール・マグヌス・リーベル：ノルディック複合の支配的な力", "zh": "Jarl Magnus Riiber: Beiou Fushi de Zhupei Liliang", "ko": "야를 마그누스 리베르: 노르딕 복합의 지배적인 힘"}'::jsonb,
    '{"en": "The Norwegian has redefined what''s possible in Nordic combined, winning World Cup titles with unprecedented dominance. Simply the best in the world.", "de": "Der Norweger hat neu definiert, was in der Nordischen Kombination möglich ist.", "fr": "Le Norvégien a redéfini ce qui est possible dans le combiné nordique.", "it": "Il norvegese ha ridefinito ciò che è possibile nella combinata nordica.", "es": "El noruego ha redefinido lo que es posible en la combinada nórdica.", "pt": "O norueguês redefiniu o que é possível no combinado nórdico.", "nl": "De Noor heeft opnieuw gedefinieerd wat mogelijk is in de Noordse combinatie.", "ar": "أعاد النرويجي تعريف ما هو ممكن في الجمع الشمالي", "ja": "ノルウェー人はノルディック複合で可能なことを再定義しました。", "zh": "Nuowei ren chongxin dingyi le beiou fushi zhong keneng de dongxi.", "ko": "노르웨이인은 노르딕 복합에서 가능한 것을 재정의했습니다."}'::jsonb,
    '{"en": "<p>Jarl Magnus Riiber is the most dominant athlete in <a href=\"/nordic-combined-guide/\">Nordic combined</a> history. The Norwegian has won World Cup overall titles with such consistency that his rivals often compete for second place.</p><h2>Unprecedented Success</h2><p>Riiber''s World Cup winning record stands alone in modern Nordic combined. His ability to perform at the highest level week after week, season after season, sets him apart from every other athlete in the sport''s history.</p><p>Multiple world championship gold medals confirm his status as the definitive champion of his generation.</p><h2>Complete Athlete</h2><p>What makes Riiber extraordinary is his excellence in both disciplines. His ski jumping produces massive leads that would challenge most competitors, and his cross-country skiing ensures he extends or maintains his advantage.</p><p>He has essentially eliminated the traditional drama of Nordic combined - whether the jumpers can hold off the cross-country specialists. Riiber does both better than anyone.</p><h2>Competitive Drive</h2><p>Despite his dominance, Riiber maintains an intense competitive focus. He treats every race as a challenge to be conquered, never taking victory for granted.</p><h2>Norwegian Tradition</h2><p>Norway has produced many Nordic combined champions, but Riiber stands above them all in terms of sheer dominance. He competes against rising stars like <a href=\"/johannes-lamparter-profile/\">Johannes Lamparter</a>, but remains the man to beat.</p><h2>Legacy Building</h2><p>Riiber continues to add to his record-breaking trophy collection. When his career ends, he will be remembered as the greatest Nordic combined athlete ever to compete.</p>", "de": "<p>Jarl Magnus Riiber ist der dominanteste Athlet in der Geschichte der <a href=\"/nordic-combined-guide/\">Nordischen Kombination</a>. Der Norweger hat Weltcup-Gesamtsiege mit solcher Konstanz gewonnen.</p><h2>Beispielloser Erfolg</h2><p>Riibers Weltcup-Siegrekord steht allein in der modernen Nordischen Kombination. Seine Fähigkeit, Woche für Woche auf höchstem Niveau zu performen, unterscheidet ihn von jedem anderen Athleten.</p><h2>Kompletter Athlet</h2><p>Was Riiber außergewöhnlich macht, ist seine Exzellenz in beiden Disziplinen.</p><h2>Norwegische Tradition</h2><p>Er kämpft gegen aufstrebende Stars wie <a href=\"/johannes-lamparter-profile/\">Johannes Lamparter</a>.</p>", "fr": "<p>Jarl Magnus Riiber est l''athlète le plus dominant de l''histoire du <a href=\"/nordic-combined-guide/\">combiné nordique</a>. Le Norvégien a remporté des titres de Coupe du monde avec une régularité inégalée.</p><h2>Succès sans précédent</h2><p>Le palmarès de Riiber en Coupe du monde est unique dans le combiné nordique moderne.</p><h2>Athlète complet</h2><p>Ce qui rend Riiber extraordinaire, c''est son excellence dans les deux disciplines.</p><h2>Tradition norvégienne</h2><p>Il affronte des étoiles montantes comme <a href=\"/johannes-lamparter-profile/\">Johannes Lamparter</a>.</p>", "it": "<p>Jarl Magnus Riiber è l''atleta più dominante nella storia della <a href=\"/nordic-combined-guide/\">combinata nordica</a>. Il norvegese ha vinto titoli di Coppa del Mondo con una costanza tale che i suoi rivali spesso competono per il secondo posto.</p><h2>Successo senza precedenti</h2><p>Il record di vittorie in Coppa del Mondo di Riiber è unico nella combinata nordica moderna.</p><h2>Atleta completo</h2><p>Ciò che rende Riiber straordinario è la sua eccellenza in entrambe le discipline.</p>", "es": "<p>Jarl Magnus Riiber es el atleta más dominante en la historia de la <a href=\"/nordic-combined-guide/\">combinada nórdica</a>. El noruego ha ganado títulos de Copa del Mundo con tal consistencia que sus rivales a menudo compiten por el segundo lugar.</p><h2>Éxito sin precedentes</h2><p>El récord de victorias en Copa del Mundo de Riiber es único en la combinada nórdica moderna.</p>", "pt": "<p>Jarl Magnus Riiber é o atleta mais dominante da história do <a href=\"/nordic-combined-guide/\">combinado nórdico</a>. O norueguês ganhou títulos da Copa do Mundo com tal consistência que seus rivais frequentemente competem pelo segundo lugar.</p><h2>Sucesso sem precedentes</h2><p>O recorde de vitórias de Riiber na Copa do Mundo é único no combinado nórdico moderno.</p>", "nl": "<p>Jarl Magnus Riiber is de meest dominante atleet in de geschiedenis van de <a href=\"/nordic-combined-guide/\">Noordse combinatie</a>. De Noor heeft Wereldbeker titels gewonnen met zo''n consistentie dat zijn rivalen vaak strijden om de tweede plaats.</p><h2>Ongekend succes</h2><p>Riibers Wereldbeker winrecord staat alleen in de moderne Noordse combinatie.</p>", "ar": "<p>يارل ماغنوس ريبر هو الرياضي الأكثر هيمنة في تاريخ <a href=\"/nordic-combined-guide/\">الجمع الشمالي</a>. فاز النرويجي بألقاب كأس العالم بثبات لدرجة أن منافسيه غالباً ما يتنافسون على المركز الثاني.</p><h2>نجاح غير مسبوق</h2><p>رقم ريبر القياسي في الفوز بكأس العالم يقف وحيداً في الجمع الشمالي الحديث.</p>", "ja": "<p>ヤール・マグヌス・リーベルは、<a href=\"/nordic-combined-guide/\">ノルディック複合</a>史上最も支配的な選手です。ノルウェー人は、ライバルがしばしば2位を争うほどの一貫性でワールドカップ総合優勝を勝ち取っています。</p><h2>前例のない成功</h2><p>リーベルのワールドカップ勝利記録は、現代のノルディック複合で唯一無二です。</p>", "zh": "<p>Jarl Magnus Riiber shi <a href=\"/nordic-combined-guide/\">beiou fushi</a> lishi shang zui zhupei de yundongyuan. Nuowei ren yi ruci yiguan de fangshi yingqu Shijie Bei guanjun, ta de duishou jingchang jingzheng disanding.</p><h2>Qiansuoweiyou de chenggong</h2><p>Riiber de Shijie Bei shengli jilu zai xiandai beiou fushi zhong duyiwuer.</p>", "ko": "<p>야를 마그누스 리베르는 <a href=\"/nordic-combined-guide/\">노르딕 복합</a> 역사상 가장 지배적인 선수입니다. 노르웨이인은 라이벌들이 종종 2위를 다툴 정도로 일관되게 월드컵 종합 우승을 차지했습니다.</p><h2>전례 없는 성공</h2><p>리베르의 월드컵 우승 기록은 현대 노르딕 복합에서 유일무이합니다.</p>"}'::jsonb,
    'athlete-profile',
